import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {pathToFileURL} from 'node:url';
import path from 'node:path';
const root=process.cwd(), temporary=process.argv[2];
const target='Packages/HanlinPlatform/Sources/HanlinScriptWidgetOriginal/Original/Common/ScriptManager.swift';
const {mergeOriginal}=await import(pathToFileURL(path.join(root,'Scripts/MiniApps/refresh-original-sources.mjs')));
const local=await readFile(path.join(root,target)),previous=await readFile(path.join(temporary,'ScriptManager.upstream.swift'));
const binding='static let maximumSourceBytes = ScriptWidgetRuntimeContract.maximumTranspiledBytes';
assert.equal(local.toString().split(binding).length-1,1);
const same=await mergeOriginal({local,previous,next:previous,cache:temporary,label:'snapshot-same-version',target});
assert.deepEqual(same,local);
const marker='// Controlled unrelated upstream edit for the three-way merge probe.\n';
const next=Buffer.concat([Buffer.from(marker),previous]);
const advanced=await mergeOriginal({local,previous,next,cache:temporary,label:'snapshot-controlled-advance',target});
assert.equal(advanced.toString().split(binding).length-1,1);
assert.ok(advanced.toString().startsWith(marker));
assert.ok(!advanced.toString().includes('static let maximumSourceBytes = 2 * 1024 * 1024'));
const repeated=await mergeOriginal({local:advanced,previous:next,next,cache:temporary,label:'snapshot-repeat-after-merge',target});
assert.deepEqual(repeated,advanced);
const digest=bytes=>createHash('sha256').update(bytes).digest('hex');
console.log(JSON.stringify({status:'PASS',sameVersion:{retainsExactLocalBytes:true,sha256:digest(same)},threeWayHelper:{retainsReference:true,retainsControlledUpstreamEdit:true,idempotentAfterMerge:true,fixture:'Actual immutable upstream source with one added comment; not a newly published upstream revision'},fullSourceRefresh:'NOT_RUN',nativeAppleBuild:'NOT_RUN'}));
